/*
 * Browser evidence driver for the TTS highlight-sync fix
 * (docs/tts-round2/05-reader-highlight-sync.md).
 *
 * Loaded into ../../debug.html by playwright-cli (page.addScriptTag), then
 * driven by assets/foliate-js/debug-books/run-evidence.js.
 *
 * The synthetic book is debug-books/sync-test.epub (generated by
 * make-sync-test-epub.py):
 *   ch1 page 1: p1 (normal), p2 (footnote link after a sentence),
 *               p3 (footnote link inside a sentence), p4 (bare [12] marker)
 *   ch1 p6:     one very long sentence spanning pages
 *   ch2/ch3:    cross-section navigation targets
 *
 * The scenarios only use the public bridges the Dart reader uses
 * (window.initTts/ttsHere/ttsNextSilent/ttsCurrentDetail/nextPage/
 *  nextSection/ttsHighlightSpoken/ttsStop/ttsHighlightDebug), so they exercise
 * the same code path as the playback pipeline.
 */
(() => {
  const ANNOTATION_RE = /\[[0-9]+\]/g;
  const VIEWPORT_TOLERANCE = 2;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const view = () => window.reader && window.reader.view;
  const content = () => {
    const renderer = view() && view().renderer;
    const list = renderer && renderer.getContents ? renderer.getContents() : [];
    return list[0] || null;
  };
  const sectionIndex = () => (content() ? content().index : -1);
  const doc = () => (content() ? content().doc : null);
  const debug = () => window.ttsHighlightDebug();
  const detail = () => window.ttsCurrentDetail();

  const ready = () => !!(view() && view().lastLocation && doc());

  const waitReady = async (timeout = 20000) => {
    const started = Date.now();
    while (!ready()) {
      if (Date.now() - started > timeout) throw new Error('reader not ready');
      await sleep(50);
    }
    return true;
  };

  // The paginator ignores programmatic navigation while a page turn is in
  // flight (its locked window). Wait it out so the evidence is deterministic.
  const waitUnlocked = async (timeout = 5000) => {
    const renderer = view() && view().renderer;
    if (!renderer) return false;
    const started = Date.now();
    while (renderer.locked) {
      if (Date.now() - started > timeout) return false;
      await sleep(50);
    }
    return true;
  };

  // Spoken ranges of a sentence: the playback pipeline excludes bracket
  // annotations such as `[12]` (it does not speak them), so the highlight must
  // paint exactly the remaining spans. Footnote link text is already absent
  // from the sentence text (the reader skips local links when extracting it).
  const spokenRanges = (text) => {
    const ranges = [];
    let offset = 0;
    for (const match of text.matchAll(ANNOTATION_RE)) {
      const start = match.index;
      if (start > offset) ranges.push({ start: offset, end: start });
      offset = start + match[0].length;
    }
    if (offset < text.length) ranges.push({ start: offset, end: text.length });
    if (!ranges.length) ranges.push({ start: 0, end: text.length });
    return ranges;
  };

  const paintedText = (snapshot) => snapshot.painted.map((entry) => entry.text).join('');
  const paintedRects = (snapshot) =>
    snapshot.painted.reduce((all, entry) => all.concat(entry.rects), []);

  const rectInsideViewport = (rect) => {
    const frame = doc() && doc().defaultView;
    const width = frame ? frame.innerWidth : 0;
    if (!width) return false;
    return rect.left >= -VIEWPORT_TOLERANCE &&
      rect.right <= width + VIEWPORT_TOLERANCE &&
      rect.right - rect.left > 0 &&
      rect.bottom - rect.top > 0;
  };

  const viewportCheck = (snapshot) => {
    const frame = doc() && doc().defaultView;
    const width = frame ? frame.innerWidth : 0;
    const rects = paintedRects(snapshot);
    const failures = rects.filter((rect) => !rectInsideViewport(rect));
    return {
      pass: rects.length > 0 && failures.length === 0,
      width,
      count: rects.length,
      failures,
    };
  };

  const rectsOverlap = (a, b) => {
    const width = Math.min(a.right, b.right) - Math.max(a.left, b.left);
    const height = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
    return width > 0.5 && height > 0.5;
  };

  const currentPage = () => {
    const renderer = view().renderer;
    return { page: renderer.page, pages: renderer.pages, index: sectionIndex() };
  };

  // Advance the TTS iterator until the sentence predicate matches. This is the
  // same silent navigation the prefetch pipeline uses.
  const findSentence = async (predicate, maxSteps = 200) => {
    window.ttsHere();
    let current = detail();
    for (let step = 0; step < maxSteps; step++) {
      if (!current) return null;
      if (predicate(current)) return { detail: current, steps: step };
      const text = await window.ttsNextSilent();
      if (!text) return null;
      current = detail();
    }
    return null;
  };

  const highlight = (sentence, ranges) => window.ttsHighlightSpoken(
    sentence.cfi, ranges || spokenRanges(sentence.text));

  const makeChecks = () => {
    const list = [];
    const check = (name, value, extra) => {
      list.push({ name, pass: !!value, extra: extra === undefined ? null : extra });
      return !!value;
    };
    return { list, check };
  };
  const summarize = (title, ctx, extra) => Object.assign({
    title,
    pass: ctx.list.every((entry) => entry.pass),
    checks: ctx.list,
  }, extra || {});

  const setup = async () => {
    await waitReady();
    await waitUnlocked();
    window.initTts();
    window.ttsHere();
    return true;
  };

  // ---------------------------------------------------------------------
  // (a) Same-section manual page turn: highlight must pull the page back to
  // the sentence being read, with the exact spoken text painted on that page.
  // Split in two phases so the evidence can screenshot the "user paged away"
  // state and the "pulled back" state separately.
  // ---------------------------------------------------------------------
  const sameSectionPhase1 = async () => {
    await setup();
    const sentence = detail();
    const pageBefore = currentPage();
    await window.nextPage();
    await window.nextPage();
    await sleep(150);
    const pageAway = currentPage();
    return { sentence, pageBefore, pageAway };
  };

  const sameSectionPhase2 = async (state) => {
    const ctx = makeChecks();
    const { sentence, pageBefore, pageAway } = state;
    ctx.check('manual turns stayed in the same section',
      pageAway.index === pageBefore.index, pageAway);
    ctx.check('manual turns changed the page',
      pageAway.page !== pageBefore.page,
      { before: pageBefore.page, away: pageAway.page });

    const shown = await highlight(sentence);
    const snapshot = debug();
    ctx.check('highlightSpoken returned true', shown === true);
    ctx.check('reader shows the reading section again',
      snapshot.sectionIndex === pageBefore.index, snapshot);
    ctx.check('painted text equals the whole spoken sentence',
      paintedText(snapshot) === sentence.text,
      { painted: paintedText(snapshot), expected: sentence.text });
    const viewport = viewportCheck(snapshot);
    ctx.check('all painted rects are on the visible page',
      viewport.pass, viewport);
    ctx.check('page was pulled back to the sentence page',
      snapshot.page === pageBefore.page,
      { pageAfter: snapshot.page, pageBefore: pageBefore.page, pageAway: pageAway.page });
    return summarize('same-section pull-back', ctx);
  };

  // ---------------------------------------------------------------------
  // (b) Annotation exclusion: footnote links and `[12]` markers are never part
  // of the painted ranges, and the painted text matches the spoken text.
  // ---------------------------------------------------------------------
  const annotationExclusion = async () => {
    const ctx = makeChecks();
    await setup();

    // Footnote link after a sentence terminator: the link itself must not be
    // painted, and the sentence text must not contain the marker.
    const withLink = await findSentence((entry) => entry.text.includes('云层压得很低'));
    ctx.check('found sentence following a footnote link', !!withLink,
      withLink && withLink.detail.text);
    if (withLink) {
      const sentence = withLink.detail;
      ctx.check('footnote marker is not part of the sentence text',
        !sentence.text.includes('[1]'), sentence.text);
      const shown = await highlight(sentence);
      const snapshot = debug();
      ctx.check('highlightSpoken returned true (link sentence)', shown === true);
      ctx.check('painted text equals spoken text (link sentence)',
        paintedText(snapshot) === sentence.text,
        { painted: paintedText(snapshot), expected: sentence.text });
      ctx.check('painted rects avoid the footnote anchor',
        paintedRects(snapshot).every((rect) => {
          const anchorEl = doc().getElementById('fnref1');
          if (!anchorEl) return true;
          return !rectsOverlap(rect, anchorEl.getBoundingClientRect());
        }), snapshot.painted);
    }

    // Footnote link *inside* the sentence extent: the sentence text is
    // "他停下来想了想，又继续往前走。" while the DOM range spans the link. The
    // painted text must be split around it (no [2]).
    const midLink = await findSentence((entry) => entry.text.includes('想了想'));
    ctx.check('found sentence with a footnote link in the middle', !!midLink,
      midLink && midLink.detail.text);
    if (midLink) {
      const sentence = midLink.detail;
      ctx.check('in-sentence footnote marker is not part of the text',
        !sentence.text.includes('[2]'), sentence.text);
      const shown = await highlight(sentence);
      const snapshot = debug();
      ctx.check('highlightSpoken returned true (mid-link sentence)', shown === true);
      ctx.check('painted text equals spoken text (mid-link sentence)',
        paintedText(snapshot) === sentence.text,
        { painted: paintedText(snapshot), expected: sentence.text });
      ctx.check('multi-segment paint around the annotation',
        snapshot.painted.length >= 2, snapshot.painted.length);
      ctx.check('painted rects avoid the in-sentence footnote anchor',
        paintedRects(snapshot).every((rect) => {
          const anchorEl = doc().getElementById('fnref2');
          if (!anchorEl) return true;
          return !rectsOverlap(rect, anchorEl.getBoundingClientRect());
        }), snapshot.painted);
    }

    // Bare `[12]` text annotation: pipeline ranges exclude it, so the painted
    // text must exclude it too (it is not spoken).
    const marker = await findSentence((entry) => entry.text.includes('[12]'));
    ctx.check('found sentence with a bare [12] marker', !!marker,
      marker && marker.detail.text);
    if (marker) {
      const sentence = marker.detail;
      const ranges = spokenRanges(sentence.text);
      const expected = ranges
        .map((range) => sentence.text.slice(range.start, range.end)).join('');
      ctx.check('pipeline ranges exclude the [12] marker',
        ranges.length > 1, ranges);
      const shown = await highlight(sentence, ranges);
      const snapshot = debug();
      ctx.check('highlightSpoken returned true ([12] sentence)', shown === true);
      ctx.check('painted text excludes the [12] marker',
        paintedText(snapshot) === expected && !paintedText(snapshot).includes('[12]'),
        { painted: paintedText(snapshot), expected, original: sentence.text });
    }

    // <br> handling: the extraction counts a line break as ONE space, so the
    // character offsets after it must stay aligned even though there is no
    // glyph to paint. A suffix starting right after the <br> must paint exactly
    // the suffix text (a mis-count would shift the highlight).
    const lineBreak = await findSentence((entry) => entry.text.includes('院子里静悄悄的'));
    ctx.check('found sentence containing a <br>', !!lineBreak,
      lineBreak && lineBreak.detail.text);
    if (lineBreak) {
      const sentence = lineBreak.detail;
      ctx.check('extraction counts the <br> as one space',
        sentence.text.includes('木门 院子'), sentence.text);
      const suffixStart = sentence.text.indexOf('院子里');
      const suffix = sentence.text.slice(suffixStart);
      const shown = await highlight(sentence, [
        { start: suffixStart, end: sentence.text.length },
      ]);
      const snapshot = debug();
      ctx.check('highlightSpoken returned true (<br> sentence)', shown === true);
      ctx.check('offset after a <br> maps to the right DOM text',
        paintedText(snapshot) === suffix,
        { painted: paintedText(snapshot), expected: suffix });
      ctx.check('painted text survives the synthetic <br> space',
        paintedText(snapshot).replace(/\s+/g, '') ===
          suffix.replace(/\s+/g, ''),
        paintedText(snapshot));
    }
    return summarize('annotation exclusion', ctx);
  };

  // ---------------------------------------------------------------------
  // (c) Repeated highlight: a new sentence replaces the previous overlay
  // instead of leaving a stale selection behind.
  // ---------------------------------------------------------------------
  const repeatedHighlight = async () => {
    const ctx = makeChecks();
    await setup();
    const first = await findSentence((entry) => entry.text.includes('云层压得很低'));
    const second = await findSentence((entry) => entry.text.includes('笔记'));
    ctx.check('found both sentences', !!first && !!second);
    if (first && second) {
      const spokenSecond = spokenRanges(second.detail.text)
        .map((range) => second.detail.text.slice(range.start, range.end)).join('');
      await highlight(first.detail);
      const afterFirst = debug();
      await highlight(second.detail);
      const afterSecond = debug();
      ctx.check('first paint had text',
        paintedText(afterFirst) === first.detail.text,
        { painted: paintedText(afterFirst) });
      ctx.check('second paint only contains the second sentence',
        paintedText(afterSecond) === spokenSecond,
        { painted: paintedText(afterSecond), expected: spokenSecond });
      ctx.check('no stale overlay from the first sentence',
        !paintedText(afterSecond).includes('云层'),
        { painted: paintedText(afterSecond) });
    }
    return summarize('repeated highlight cleanup', ctx);
  };

  // ---------------------------------------------------------------------
  // (c) Page-split sentence: `.a` is painted on the first page, `.b` on the
  // next one; the `.b` paint must move the page and drop the `.a` overlay.
  // ---------------------------------------------------------------------
  const pageSplit = async () => {
    const ctx = makeChecks();
    await setup();
    const found = await findSentence((entry) => entry.text.length > 700);
    ctx.check('found the long sentence', !!found,
      found && found.detail.text.length);
    if (!found) return summarize('page-split .a/.b', ctx);
    const sentence = found.detail;
    const total = sentence.text.length;

    // Locate an offset that really falls on a later page: paint the prefix and
    // compare pages, then paint the remainder.
    let aPage = null;
    let bPage = null;
    let offset = 0;
    for (const fraction of [0.4, 0.5, 0.6, 0.7, 0.8]) {
      offset = Math.floor(total * fraction);
      await highlight(sentence, [{ start: 0, end: offset }]);
      aPage = debug().page;
      await highlight(sentence, [{ start: offset, end: total }]);
      bPage = debug().page;
      if (bPage !== aPage) break;
    }
    ctx.check('painted .b moved the reader to a later page', bPage > aPage,
      { aPage, bPage, offset, total });
    const snapshot = debug();
    const expectedB = sentence.text.slice(offset);
    ctx.check('painted text is exactly the .b half',
      paintedText(snapshot) === expectedB,
      { paintedLength: paintedText(snapshot).length, expectedLength: expectedB.length });
    const viewport = viewportCheck(snapshot);
    ctx.check('painted rects are on the visible page', viewport.pass, viewport);
    ctx.check('the .a half is not highlighted anymore',
      !paintedText(snapshot).startsWith(sentence.text.slice(0, 40)),
      paintedText(snapshot).slice(0, 40));
    return summarize('page-split .a/.b', ctx, { aPage, bPage, offset, total });
  };

  // ---------------------------------------------------------------------
  // (d) Cross-section manual navigation: highlighting the sentence being read
  // pulls the reader back to its section, and the TTS iterator still advances
  // to the *next* sentence afterwards (no skipped or duplicated sentence).
  // Split in two phases for the "user elsewhere" and "pulled back" screenshots.
  // ---------------------------------------------------------------------
  const crossSectionPhase1 = async () => {
    await waitReady();
    await waitUnlocked();
    window.initTts();
    window.ttsHere();
    const first = detail();
    const secondText = await window.ttsNextSilent();
    const second = detail();
    // Clear the legacy whole-sentence paint done by ttsHere()/from() so the
    // "nothing is painted while the user looks elsewhere" check is meaningful.
    window.ttsStop();
    await waitUnlocked();
    await window.nextSection();
    await waitUnlocked();
    await sleep(300);
    const awayPage = currentPage();
    return { first, second, secondText, awayPage, paintedAway: debug().painted.length };
  };

  const crossSectionPhase2 = async (state) => {
    const ctx = makeChecks();
    const { first, second, awayPage, paintedAway } = state;
    ctx.check('collected first two sentences', !!first && !!second,
      { first: first && first.text, second: second && second.text });
    ctx.check('user is now in another section', awayPage.index === 1, awayPage);
    ctx.check('no highlight is painted on the user page', paintedAway === 0,
      paintedAway);

    // The iterator still belongs to the reading section: currentDetail must
    // return the reading sentence (and its reading-section CFI), not the first
    // sentence of the page the user is looking at. This is what used to reset
    // the position and paint a "fake selection" on the wrong page.
    const readingText = await window.ttsNextSilent();
    const readingDetail = detail();
    ctx.check('advance keeps reading in the original section while user looks away',
      typeof readingText === 'string' && readingText.length > 0 &&
      readingDetail && readingDetail.cfi && readingDetail.cfi.includes('/6/2!'),
      { readingText, readingCfi: readingDetail && readingDetail.cfi });

    // Playback now starts the second sentence: pull the page back and paint it.
    const shown = await highlight(second);
    const snapshot = debug();
    const pulledPage = currentPage();
    ctx.check('highlightSpoken returned true across sections', shown === true);
    ctx.check('reader pulled back to the reading section',
      snapshot.sectionIndex === 0 && pulledPage.index === 0,
      { sectionIndex: snapshot.sectionIndex, pulledIndex: pulledPage.index });
    ctx.check('painted text is the second sentence',
      paintedText(snapshot) === second.text,
      { painted: paintedText(snapshot), expected: second.text });
    const viewport = viewportCheck(snapshot);
    ctx.check('painted rects are on the visible page', viewport.pass, Object.assign({
      paintedCount: snapshot.painted.length,
      rectsPerPaint: snapshot.painted.map((entry) => entry.rects.length),
      contentsLen: (view() && view().renderer.getContents().length) || 0,
    }, viewport));

    // Iterator was pinned at the sentence being spoken during the rebuild, so
    // the next advance continues with the sentence after it.
    const nextText = await window.ttsNextSilent();
    const nextDetail = detail();
    ctx.check('next advance continues after the painted sentence',
      nextText === readingText, { nextText, expected: readingText });
    ctx.check('next detail cfi matches the collected reading sentence',
      nextDetail && nextDetail.cfi === readingDetail.cfi,
      { nextCfi: nextDetail && nextDetail.cfi, expected: readingDetail.cfi });
    return summarize('cross-section pull-back', ctx, {
      firstText: first && first.text,
      secondText: second.text,
      readingText,
      pulledPage,
    });
  };

  // ---------------------------------------------------------------------
  // (e) ttsStop clears every overlay; a following highlight starts clean.
  // ---------------------------------------------------------------------
  const stopClears = async () => {
    const ctx = makeChecks();
    await setup();
    const sentence = detail();
    await highlight(sentence);
    ctx.check('painted before stop', debug().painted.length > 0);
    window.ttsStop();
    const afterStop = debug();
    ctx.check('ttsStop removed all overlays', afterStop.painted.length === 0,
      afterStop);
    await highlight(sentence);
    ctx.check('a later highlight paints again', debug().painted.length > 0);
    return summarize('ttsStop cleanup', ctx);
  };

  // ---------------------------------------------------------------------
  // (f) Bridge latency: `highlightSpoken` is called before every engine
  // request; it must stay well inside the Dart-side 800 ms bound, including
  // the cross-section pull-back (navigation + section reload + repaint).
  // ---------------------------------------------------------------------
  const latencyProbe = async () => {
    const ctx = makeChecks();
    await setup();
    const sameSection = [];
    let sentence = detail();
    for (let index = 0; index < 8; index++) {
      const ranges = spokenRanges(sentence.text);
      const started = performance.now();
      const shown = await window.ttsHighlightSpoken(sentence.cfi, ranges);
      sameSection.push({
        ms: Math.round((performance.now() - started) * 10) / 10,
        shown,
      });
      const text = await window.ttsNextSilent();
      if (!text) break;
      sentence = detail();
    }
    ctx.check('every same-section highlight succeeded',
      sameSection.every((entry) => entry.shown), sameSection);

    await waitUnlocked();
    await window.nextSection();
    await waitUnlocked();
    await sleep(200);
    const started = performance.now();
    const shown = await window.ttsHighlightSpoken(
      sentence.cfi, spokenRanges(sentence.text));
    const crossSectionMs = Math.round((performance.now() - started) * 10) / 10;
    ctx.check('cross-section highlight succeeded', shown === true);
    ctx.check('cross-section highlight inside the 800 ms Dart bound',
      crossSectionMs < 800, { crossSectionMs });
    return summarize('bridge latency', ctx, {
      sameSection,
      crossSection: { ms: crossSectionMs, shown },
    });
  };

  window.__anxSync = {
    version: 1,
    waitReady,
    waitUnlocked,
    spokenRanges,
    currentPage,
    debug,
    detail,
    sameSectionPhase1,
    sameSectionPhase2,
    annotationExclusion,
    repeatedHighlight,
    pageSplit,
    crossSectionPhase1,
    crossSectionPhase2,
    stopClears,
    latencyProbe,
  };
})();
